/// <summary>
/// Service class which updates the vendor payment statuses for Metpay payment journal lines 
/// </summary>
public class METPaymentStatusUpdateService extends SysOperationServiceBase
{
    #OCCRetryCount

    METProcessingStatus                         processingStatus;
    ErrorMessage                                processingMessage;
    DataAreaId                                  dataAreaId;
    Filename                                    fileName;

}

Method.Source:
    /// <summary>
    /// Service operation method to update the payment statuses of the METPAY payment lines
    /// </summary>
    /// <param name="_paymentStatusUpdateContract">
    /// The instance of <c>METPaymentStatusUpdateContract</c>
    /// </param>
    /// <returns>
    /// The response <c>METPurchaseOrderContract</c>
    /// </returns>
    public METPaymentStatusUpdateResponse updatePaymentStatus(METPaymentStatusUpdateContract _paymentStatusUpdateContract)
    {
        METProcessingStatus     result;
        ErrorMessage            message;

        [result, message] = this.run(_paymentStatusUpdateContract);
        
        return METPaymentStatusUpdateResponse::newFromParameters(result, message);
    }

/// <summary>
/// Initialise parameters.
/// </summary>
/// <param name="_paymentStatusUpdateContract">Instance of METPaymentStatusUpdateContract class</param>
private void initParams(METPaymentStatusUpdateContract _paymentStatusUpdateContract)
{
    processingStatus                        = METProcessingStatus::None;
    dataAreaId                              = _paymentStatusUpdateContract.parmDataAreaId();
    fileName                                = _paymentStatusUpdateContract.parmFileName();
}

    /// <summary>
    /// Validate the parameters
    /// </summary>
    /// <returns>container</returns>
    private container validate()
    {
        if (!dataAreaId)
        {
            processingMessage = strFmt("@SYS84753", "@SYS177726");
        }
        else if (!fileName)
        {
            processingMessage = "@SYS4081574";
        }

        if (processingMessage)
        {
            processingStatus = METProcessingStatus::Error;
        }

        return [processingStatus, processingMessage];
    }

    /// <summary>
    /// This method contains the logic to update the payment statuses that are related to METPAY filename
    /// </summary>
    /// <param name="_paymentStatusUpdateContract">List of contracts</param>
    /// <returns>Container of Results</returns>
    public container run(METPaymentStatusUpdateContract _paymentStatusUpdateContract)
    {
        this.initParams(_paymentStatusUpdateContract);

        changecompany(dataAreaId)
        {

            [processingStatus, processingMessage] = this.validate();

            if (processingStatus == METProcessingStatus::Error)
            {
                return [processingStatus, processingMessage];
            }

            try
            {
                if (fileName)
                {
                    ttsbegin;
                    this.runUpdate(CustVendPaymStatus::METDueDateSent, CustVendPaymStatus::METDueDateUpdated);

                    this.runUpdate(CustVendPaymStatus::METWithdrawSent, CustVendPaymStatus::METWithdrawn);

                    this.runUpdate(CustVendPaymStatus::METResendSent, CustVendPaymStatus::METResent);
                    ttscommit;

                    processingStatus = METProcessingStatus::Success;
                }
                
              
            }

            catch (Exception::Deadlock)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        processingMessage = "@WAX:DeadlockExceptionMessage";
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    processingMessage = "@WAX:DeadlockExceptionMessage";
                }
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        processingMessage = "@WAX:UpdateConflictExceptionMessage";
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    processingMessage = "@WAX:UpdateConflictExceptionMessage";
                }
            }
            catch
            {
                processingMessage = "@WAX:UpdateCancelled";
            }

        }

        if (processingMessage)
        {
            processingStatus = METProcessingStatus::Error;
        }

        return [processingStatus, processingMessage];
    }

/// <summary>
/// Bulk update payments
/// </summary>
/// <param name = "_fromStatus">CustVendPaymStatus</param>
/// <param name = "_toStatus">CustVendPaymStatus</param>
private void runUpdate(CustVendPaymStatus    _fromStatus, 
                        CustVendPaymStatus    _toStatus)
{
    LedgerJournalTrans      ledgerJournalTrans;
    if (fileName)
    {
        ledgerJournalTrans.skipDataMethods(true);
        update_recordset ledgerJournalTrans
            setting PaymentStatus = _toStatus
            where ledgerJournalTrans.PaymentStatus == _fromStatus
            && ledgerJournalTrans.METInvFileName == fileName;
    }
}
